import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl and other polyglot runtimes","description":"","frontmatter":{},"headers":[],"relativePath":"handl/explanation/polyglot-runtimes.md","filePath":"vendored/handl/explanation/polyglot-runtimes.md"}`),a={name:`handl/explanation/polyglot-runtimes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-and-other-polyglot-runtimes" tabindex="-1"><code>handl</code> and other polyglot runtimes <a class="header-anchor" href="#handl-and-other-polyglot-runtimes" aria-label="Permalink to “handl and other polyglot runtimes”">​</a></h1><p><code>handl</code> is <strong>not the first polyglot runtime</strong>. Several systems already run multiple languages or syntaxes in the same process. What makes <code>handl</code> different is the <em>plugin-driven, self-hosting composer</em> model.</p><h2 id="existing-polyglot-runtimes" tabindex="-1">Existing polyglot runtimes <a class="header-anchor" href="#existing-polyglot-runtimes" aria-label="Permalink to “Existing polyglot runtimes”">​</a></h2><table tabindex="0"><thead><tr><th>runtime</th><th>how it is polyglot</th></tr></thead><tbody><tr><td><strong>GraalVM / Truffle</strong></td><td>Languages are implemented as Truffle interpreters on a shared JVM. They share a common <code>Polyglot</code> API and can pass values directly.</td></tr><tr><td><strong>.NET CLR</strong></td><td>C#, F#, VB, and others compile to Common Intermediate Language (CIL) and run on the same VM.</td></tr><tr><td><strong>JVM</strong></td><td>Java, Kotlin, Scala, Clojure, and others share the Java Virtual Machine and bytecode.</td></tr><tr><td><strong>BEAM</strong></td><td>The Erlang/Elixir runtime also hosts Luerl, Clojure-erl, and other languages.</td></tr><tr><td><strong>WebAssembly</strong></td><td>C, C++, Rust, Go, and many others compile to WASM and run in the same sandbox.</td></tr><tr><td><strong>inauguration / .in</strong></td><td>Multi-frontend parser that uses Tree-sitter to ingest Swift, C, Rust, Go, Python, and more, then lowers them into a unified Core IR.</td></tr><tr><td><strong>inlang / Fink</strong></td><td>Similar idea: multiple language fronts, one intermediate representation.</td></tr><tr><td><strong>Cornell Polyglot</strong></td><td>An extensible Java front-end for Java dialects.</td></tr></tbody></table><p>These systems are mature and well-tested. They prove that polyglot execution is possible.</p><h2 id="how-handl-is-different" tabindex="-1">How <code>handl</code> is different <a class="header-anchor" href="#how-handl-is-different" aria-label="Permalink to “How handl is different”">​</a></h2><p>The existing systems are mostly <strong>&quot;one big VM, many languages compiled to a common IR.&quot;</strong> <code>handl</code> takes a different path:</p><ol><li><p><strong>Languages are plugins.</strong> A new syntax is not a compiler back-end or a VM target. It is <code>Language</code> data plus a set of <code>Behavior</code> rules contributed by plugins — the rules produce and consume the same <code>AstNode</code> type.</p></li><li><p><strong>The host is the runtime composer.</strong> The <code>Host</code> loads plugins, resolves dependencies, and assembles the language. It does not define the language itself. The language is the <em>composition</em> of the loaded plugins.</p></li><li><p><strong>The language can host and spawn hosts.</strong> Because the <code>Host</code> is minimal and plugin-based, a <code>handl</code> program can eventually create and configure new <code>Host</code> instances. This makes <code>handl</code> able to describe its own runtime composition.</p></li><li><p><strong>Sandboxing by design.</strong> Capabilities such as <code>contribute</code>, <code>register-plugin</code>, and <code>execute</code> can be tracked as <code>handl</code> effects. A module that does not declare a capability cannot use it, even if it is loaded.</p></li></ol><h2 id="what-is-arguably-new" tabindex="-1">What is arguably new <a class="header-anchor" href="#what-is-arguably-new" aria-label="Permalink to “What is arguably new”">​</a></h2><p>It would be inaccurate to claim that <code>handl</code> is the first polyglot runtime. It is more precise to say:</p><blockquote><p><code>handl</code> may be the first polyglot runtime built around a universal <code>Plugin</code> model where the parser, lexer, formatter, and typechecker are all composable rule sets, and where the host itself can be written and spawned from within the language.</p></blockquote><p>That model — a <code>Plugin</code> graph that assembles languages, and a language that can assemble its own runtime — is the novel part. In short, <code>handl</code> aims to be a <strong>self-describing, self-hosting, capability-sandboxed polyglot composer</strong>.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};